def uid_test(client_socket):
    # 绑定
    binduid = bytes.fromhex(cmddatamap["binduid"])
    client_socket.send(binduid)
    # 发送给uid
    senduid = bytes.fromhex(cmddatamap["sendtouid"])
    client_socket.send(senduid)
    # 解绑uid
    unbinduid = bytes.fromhex(cmddatamap["unbinduid"])
    client_socket.send(unbinduid)

    # 绑定多个uid
    client_socket.send(binduid)
    binuid2 = bytes.fromhex(cmddatamap["binuid2"])
    client_socket.send(binuid2)
    # 通过uid获取cid 需要两个客户端连接
    GetClientIdByUid = bytes.fromhex(cmddatamap["GetClientIdByUid"])
    client_socket.send(GetClientIdByUid)
    GetClientIdsByUid = bytes.fromhex(cmddatamap["GetClientIdsByUid"])
    client_socket.send(GetClientIdsByUid)


def gid_test(client_socket):
    # 加入组
    joingroup = bytes.fromhex(cmddatamap["joingroup"])
    client_socket.send(joingroup)
    # join多个group
    joingroup2 = bytes.fromhex(cmddatamap["joingroup2"])
    client_socket.send(joingroup2)
    # 发送给gid
    sendgroup = bytes.fromhex(cmddatamap["sendtogroup"])
    client_socket.send(sendgroup)
    # 离开组
    leavegroup = bytes.fromhex(cmddatamap["leavegroup"])
    client_socket.send(leavegroup)

    # 根据gid获取用户数
    client_socket.send(joingroup)
    # 根据gid获取用户数
    GetClientCountByGroup = bytes.fromhex(cmddatamap["GetClientCountByGroup"])
    client_socket.send(GetClientCountByGroup)
    # 获取所有在线用户
    getallclientcount = bytes.fromhex(cmddatamap["getallclientcount"])
    client_socket.send(getallclientcount)

    # sendto one
    sendtoone = bytes.fromhex(cmddatamap["sendtoone"])
    client_socket.send(sendtoone)

    # sendto all
    sendtoall = bytes.fromhex(cmddatamap["sendtoall"])
    client_socket.send(sendtoall)

def session_test(client_socket):
    # 设置session
    setsession = bytes.fromhex(cmddatamap["setsession"])
    client_socket.send(setsession)
    cid2_setsession = bytes.fromhex(cmddatamap["cid2_setsession"])
    client_socket.send(cid2_setsession)
    # 获取session
    GetSession = bytes.fromhex(cmddatamap["GetSession"])
    client_socket.send(GetSession)
    # 更新session
    updatesession = bytes.fromhex(cmddatamap["updatesession"])
    client_socket.send(updatesession)
    # 获取组内所有的session
    joingroup = bytes.fromhex(cmddatamap["joingroup"])
    client_socket.send(joingroup)
    cid2_joingroup = bytes.fromhex(cmddatamap["cid2_joingroup"])
    client_socket.send(cid2_joingroup)
    GetClientSessionsByGroup = bytes.fromhex(cmddatamap["GetClientSessionsByGroup"])
    client_socket.send(GetClientSessionsByGroup)

def start_as_worker(client_socket):
    # worker 连接   长连接
    workerconnect = bytes.fromhex(cmddatamap["workerconnect"])
    client_socket.send(workerconnect)


def start_as_gatewaycli(client_socket):
    # gateway client 连接  短连接
    gatewayconnect = bytes.fromhex(cmddatamap["gatewayconnect"])
    client_socket.send(gatewayconnect)


def bwconn_test(client_socket):
    start_as_worker(client_socket)

def closecliconn_test(client_socket):
    # 关闭客户端连接
    closeclient = bytes.fromhex(cmddatamap["closeclient"])
    client_socket.send(closeclient)
    